package services

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const (
	pmaHideBegin = "// BEGIN SLD-HIDE-DB"
	pmaHideEnd   = "// END SLD-HIDE-DB"
)

// PhpMyAdminHideSnippet is a config fragment phpMyAdmin can include.
func PhpMyAdminHideSnippet() string {
	return fmt.Sprintf(`<?php
/**
 * Generated by Supreme Local Dev. Regenerated on install/start.
 */
if (!isset($i)) {
    $i = 1;
}
$cfg['Servers'][$i]['hide_db'] = '%s';
$cfg['NavigationTreeEnableGrouping'] = false;
`, PhpMyAdminHideDbPattern())
}

func phpMyAdminHideBlock() string {
	return fmt.Sprintf(`%s
if (!isset($i)) { $i = 1; }
$cfg['Servers'][$i]['hide_db'] = '%s';
$cfg['NavigationTreeEnableGrouping'] = false;
%s
`, pmaHideBegin, PhpMyAdminHideDbPattern(), pmaHideEnd)
}

// ApplyPhpMyAdminHideConfig writes hide_db into known phpMyAdmin config locations.
// Missing paths are skipped so a machine without phpMyAdmin still starts.
func ApplyPhpMyAdminHideConfig() error {
	snippet := PhpMyAdminHideSnippet()
	block := phpMyAdminHideBlock()

	writeTargets := []string{
		"/var/lib/sld/runtime/pma-hide-db.php",
		"/etc/phpmyadmin/conf.d/sld-hide-db.php",
	}

	var lastErr error
	for _, path := range writeTargets {
		if err := writeIfDirOK(path, snippet); err != nil {
			lastErr = err
		}
	}

	upsertTargets := []string{
		"/etc/phpmyadmin/config.inc.php",
		"/usr/share/phpmyadmin/config.inc.php",
		"/opt/lampp/phpmyadmin/config.inc.php",
	}
	for _, path := range upsertTargets {
		if err := upsertMarkedPHP(path, block); err != nil {
			lastErr = err
		}
	}

	return lastErr
}

func writeIfDirOK(path, contents string) error {
	dir := filepath.Dir(path)
	if _, err := os.Stat(dir); err != nil {
		if os.IsNotExist(err) {
			if dir == "/var/lib/sld/runtime" {
				if mkErr := os.MkdirAll(dir, 0755); mkErr != nil {
					return mkErr
				}
			} else {
				return nil
			}
		} else {
			return err
		}
	}
	return os.WriteFile(path, []byte(contents), 0644)
}

func upsertMarkedPHP(path, block string) error {
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}

	content := string(data)
	updated, changed := replaceMarkedBlock(content, block)
	if !changed {
		return nil
	}
	return os.WriteFile(path, []byte(updated), 0644)
}

func replaceMarkedBlock(content, block string) (string, bool) {
	start := strings.Index(content, pmaHideBegin)
	end := strings.Index(content, pmaHideEnd)
	if start >= 0 && end > start {
		end += len(pmaHideEnd)
		next := content[:start] + strings.TrimSuffix(block, "\n") + content[end:]
		if next == content {
			return content, false
		}
		return next, true
	}
	trimmed := strings.TrimRight(content, " \t\r\n")
	if strings.HasSuffix(trimmed, "?>") {
		trimmed = strings.TrimSuffix(trimmed, "?>")
		trimmed = strings.TrimRight(trimmed, " \t\r\n")
	}
	return trimmed + "\n" + block, true
}
